    // How long shutdown waits for the consumer-group leave handshake.
    private static readonly TimeSpan ConsumerCloseTimeout = TimeSpan.FromSeconds(5);

    public override void Dispose()
    {
        // `IConsumer.Close()` is a blocking librdkafka call with no timeout
        // overload: with no reachable broker it retries the group coordinator
        // forever, wedging host shutdown -- and with it any in-process test
        // host that booted this service. The close and the handle disposal
        // share one background task, so abandoning the wait can never race a
        // close that is still running.
        var close = System.Threading.Tasks.Task.Run(() =>
        {
            _consumer.Close();
            _consumer.Dispose();
        });
        close.Wait(ConsumerCloseTimeout);
        base.Dispose();
    }
